"use client";

import Image from "next/image";
import { useTranslations } from "next-intl";
import { Product } from "@/lib/api";

interface Props {
  product: Product;
  onAdd?: () => void;
  onClick?: () => void;
  compact?: boolean;
}

export default function ProductCard({ product, onAdd, onClick, compact }: Props) {
  const t = useTranslations("product");

  return (
    <div
      onClick={onClick}
      className={`flex items-center gap-3 px-4 py-3 hover:bg-cream-100 cursor-pointer transition-colors border-b border-cream-200 last:border-0 ${compact ? "py-2" : ""}`}
    >
      {/* Image */}
      <div className="w-12 h-12 rounded-xl bg-cream-200 flex-shrink-0 overflow-hidden flex items-center justify-center">
        {product.image_url ? (
          <Image
            src={product.image_url}
            alt={product.name}
            width={48}
            height={48}
            className="object-contain w-full h-full"
            onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}
          />
        ) : (
          <span className="text-xl">📦</span>
        )}
      </div>

      {/* Info */}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-walnut-900 truncate">{product.name}</p>
        {product.brand && (
          <p className="text-xs text-walnut-400">{product.brand}</p>
        )}
      </div>

      {/* Add to basket button */}
      {onAdd && (
        <button
          onClick={(e) => { e.stopPropagation(); onAdd(); }}
          className="flex-shrink-0 w-8 h-8 rounded-lg bg-walnut-600 hover:bg-walnut-700 text-white flex items-center justify-center transition-colors"
          title={t("addToBasket")}
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" />
          </svg>
        </button>
      )}
    </div>
  );
}
