"use client";

import { useTranslations, useLocale } from "next-intl";
import { useState } from "react";
import { useBasket } from "@/lib/basket-store";
import { compareBasket, BasketCompareResponse } from "@/lib/api";
import { searchProducts, Product } from "@/lib/api";
import BasketResults from "./BasketResults";

export default function BasketBuilder() {
  const t = useTranslations("basket");
  const tHero = useTranslations("hero");
  const tCommon = useTranslations("common");
  const locale = useLocale();
  const { items, addItem, removeItem, updateQuantity, clearBasket } = useBasket();

  const [query, setQuery] = useState("");
  const [suggestions, setSuggestions] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);
  const [comparing, setComparing] = useState(false);
  const [results, setResults] = useState<BasketCompareResponse | null>(null);
  const [debounce, setDebounce] = useState<ReturnType<typeof setTimeout>>();

  const handleSearch = (q: string) => {
    setQuery(q);
    if (debounce) clearTimeout(debounce);
    if (!q.trim()) { setSuggestions([]); return; }
    setDebounce(setTimeout(async () => {
      const res = await searchProducts(q, 6);
      setSuggestions(res);
    }, 300));
  };

  const handleCompare = async () => {
    if (!items.length) return;
    setComparing(true);
    setResults(null);
    const res = await compareBasket(items.map((i) => ({ barcode: i.barcode, quantity: i.quantity })));
    setResults(res);
    setComparing(false);
  };

  return (
    <div className="space-y-4">
      {/* Search to add products */}
      <div className="relative">
        <input
          type="text"
          value={query}
          onChange={(e) => handleSearch(e.target.value)}
          placeholder={tHero("basketPlaceholder")}
          className="w-full bg-white rounded-2xl px-5 py-4 text-walnut-900 placeholder-walnut-300 text-base focus:outline-none focus:ring-2 focus:ring-walnut-400 shadow-sm"
          dir="auto"
        />

        {/* Autocomplete dropdown */}
        {suggestions.length > 0 && query && (
          <div className="absolute top-full start-0 end-0 mt-2 bg-white rounded-2xl shadow-float border border-cream-300 overflow-hidden z-50">
            {suggestions.map((p) => (
              <div
                key={p.barcode}
                onClick={() => {
                  addItem({ barcode: p.barcode, name: p.name, brand: p.brand, imageUrl: p.image_url });
                  setQuery("");
                  setSuggestions([]);
                }}
                className="flex items-center gap-3 px-4 py-3 hover:bg-cream-100 cursor-pointer transition-colors border-b border-cream-200 last:border-0"
              >
                <span className="text-lg">📦</span>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-walnut-900 truncate">{p.name}</p>
                  {p.brand && <p className="text-xs text-walnut-400">{p.brand}</p>}
                </div>
                <span className="text-xs text-walnut-400 flex-shrink-0">+ {t("items").split(" ")[0]}</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Basket items */}
      {items.length > 0 ? (
        <div className="bg-white/10 rounded-2xl overflow-hidden border border-white/10">
          <div className="flex items-center justify-between px-4 py-2.5 border-b border-white/10">
            <span className="text-sm text-walnut-200 font-medium">
              {items.length} {t("items")}
            </span>
            <button
              onClick={clearBasket}
              className="text-xs text-walnut-400 hover:text-walnut-200 transition-colors"
            >
              {t("clear")}
            </button>
          </div>

          <div className="max-h-40 overflow-y-auto divide-y divide-white/5">
            {items.map((item) => (
              <div key={item.barcode} className="flex items-center gap-3 px-4 py-2.5">
                <span className="flex-1 text-sm text-white truncate">{item.name}</span>
                <div className="flex items-center gap-1.5 flex-shrink-0">
                  <button
                    onClick={() => updateQuantity(item.barcode, item.quantity - 1)}
                    className="w-6 h-6 rounded-md bg-white/10 hover:bg-white/20 text-white text-xs font-bold transition-colors flex items-center justify-center"
                  >−</button>
                  <span className="text-sm text-white w-5 text-center font-medium">{item.quantity}</span>
                  <button
                    onClick={() => updateQuantity(item.barcode, item.quantity + 1)}
                    className="w-6 h-6 rounded-md bg-white/10 hover:bg-white/20 text-white text-xs font-bold transition-colors flex items-center justify-center"
                  >+</button>
                  <button
                    onClick={() => removeItem(item.barcode)}
                    className="w-6 h-6 rounded-md bg-white/5 hover:bg-red-500/30 text-walnut-300 hover:text-red-300 transition-colors flex items-center justify-center ms-1"
                  >
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              </div>
            ))}
          </div>

          {/* Compare button */}
          <div className="px-4 py-3 border-t border-white/10">
            <button
              onClick={handleCompare}
              disabled={comparing}
              className="w-full py-3 rounded-xl bg-walnut-400 hover:bg-walnut-300 disabled:opacity-60 disabled:cursor-not-allowed text-walnut-900 font-bold text-sm transition-colors shadow-sm"
            >
              {comparing ? (
                <span className="flex items-center justify-center gap-2">
                  <span className="w-4 h-4 border-2 border-walnut-700 border-t-transparent rounded-full animate-spin" />
                  {tCommon("loading")}
                </span>
              ) : (
                `🔍 ${t("compareAll")}`
              )}
            </button>
          </div>
        </div>
      ) : (
        <div className="text-center py-6 text-walnut-300 text-sm">
          {t("empty")}
        </div>
      )}

      {/* Results */}
      {results && <BasketResults results={results} />}
    </div>
  );
}
