"use client";

import { useTranslations, useLocale } from "next-intl";
import { useState, useCallback, useRef } from "react";
import SearchBar from "@/components/search/SearchBar";
import BasketBuilder from "@/components/basket/BasketBuilder";

export default function HeroSection() {
  const t = useTranslations("hero");
  const locale = useLocale();
  const isRtl = locale === "he";
  const [activeTab, setActiveTab] = useState<"basket" | "search">("basket");

  return (
    <section className="relative overflow-hidden bg-gradient-to-b from-walnut-800 to-walnut-900 text-white">
      {/* Decorative grain overlay */}
      <div className="absolute inset-0 opacity-[0.03] bg-[url('data:image/svg+xml;base64,')]" />

      {/* Walnut wood texture accent */}
      <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-walnut-400/40 to-transparent" />

      <div className="relative max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-16 md:py-24">

        {/* Headline */}
        <div className="text-center mb-10">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-walnut-700/60 border border-walnut-500/30 text-walnut-200 text-xs font-medium mb-5 backdrop-blur-sm">
            <span className="w-1.5 h-1.5 rounded-full bg-sage-400 animate-pulse" />
            {locale === "he" ? "נתונים בזמן אמת מ-29 רשתות" : "Real-time data from 29 chains"}
          </div>
          <h1 className="text-4xl md:text-6xl font-bold tracking-tight text-white mb-4 leading-tight">
            {t("tagline")}
          </h1>
          <p className="text-walnut-200 text-lg md:text-xl max-w-2xl mx-auto leading-relaxed">
            {t("subtitle")}
          </p>
        </div>

        {/* Tab switcher */}
        <div className="flex justify-center mb-6">
          <div className="flex bg-walnut-900/60 border border-walnut-600/30 rounded-2xl p-1 backdrop-blur-sm">
            {(["basket", "search"] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-6 py-2.5 rounded-xl text-sm font-semibold transition-all duration-200 ${
                  activeTab === tab
                    ? "bg-white text-walnut-800 shadow-sm"
                    : "text-walnut-300 hover:text-white"
                }`}
              >
                {tab === "basket"
                  ? (isRtl ? "🛒 " : "🛒 ") + t("basketTab")
                  : (isRtl ? "🔍 " : "🔍 ") + t("searchTab")}
              </button>
            ))}
          </div>
        </div>

        {/* Main interaction area */}
        <div className="bg-white/10 backdrop-blur-md border border-white/10 rounded-3xl p-4 md:p-6 shadow-float">
          {activeTab === "basket" ? (
            <BasketBuilder />
          ) : (
            <SearchBar />
          )}
        </div>
      </div>
    </section>
  );
}
